func ErrorDetailContainsFold(v string) predicate.PublishItem {
	return predicate.PublishItem(sql.FieldContainsFold(FieldErrorDetail, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PublishItem) predicate.PublishItem {
	return predicate.PublishItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PublishItem) predicate.PublishItem {
	return predicate.PublishItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PublishItem) predicate.PublishItem {
	return predicate.PublishItem(sql.NotPredicates(p))
}
